return {["fb16_01"]={["dsc"]=[[你向杭州孤山边的石级上行去，一路欣赏着湖边长曳的杨柳。不知不觉地转了几个弯，却见遍地都是桃树，老干横斜，枝叶茂密，想像初春桃花盛开之日，香雪如海，定然观赏不尽。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb16_01]],["name"]=[[孤山石阶]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb16_02]],["visible"]=1},["fb16_02"]={["down"]=[[fb16_01]],["dsc"]=[[这条小路的两旁种着无数的桃花，虽然还没到桃花盛开的季节，但透过这密密的桃林，你似乎已经闻到了阵阵的桃花的幽香，这时你已经发现你快走到庄园的门口，你暗地里加快了脚步。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb16_02]],["name"]=[[蜿蜒小径]],["permission"]=1,["role1"]=[[fb16r02_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_03]],["visible"]=1},["fb16_03"]={["down"]=[[fb16_02]],["dsc"]=[[走过一大片桃林，走上一条青石板大路，来到一座朱门白墙的大庄院外，行到近处，见大门外写着“桃庄”两个大字，旁边署着“虞允文题”四字。那虞允文是南宋破金的大功臣，这几个字儒雅之中透着勃勃英气。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb16_03]],["item1"]=[[fb16zmdj]],["name"]=[[桃庄大门]],["permission"]=1,["role1"]=[[fb16r03_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_04]],["visible"]=1},["fb16_04"]={["down"]=[[fb16_03]],["dsc"]=[[你走过一个大天井，天井左右各植一棵老桃树，枝干如铁，极是苍劲。往南是桃庄大门，北面是大厅。]],["enterable"]=1,["id"]=[[fb16_04]],["name"]=[[大天井]],["permission"]=1,["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_05]],["visible"]=1},["fb16_05"]={["down"]=[[fb16_04]],["dsc"]=[[你已经到了桃庄的大厅门口，门内的匾额龙飞凤舞的写着“四雅清风”四个大字，笔法娟秀中透着挺拔，不失为一笔好字。透过后门，你看到里面一尘不染，一张石桌和几个石凳都安放得整整齐齐。]],["enterable"]=1,["id"]=[[fb16_05]],["name"]=[[四雅清风]],["permission"]=1,["role1"]=[[fb16r05_1]],["role2"]=[[fb16r05_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_06]],["visible"]=1},["fb16_06"]={["down"]=[[fb16_05]],["dsc"]=[[通过四雅清风，你来到了桃庄的迎客亭，这里虽然只有一张石桌几个石凳，但却是一尘不染，石凳和石桌之间的空隙很大，显是方便来客与主人相互寒暄。一位汉子正站在亭前，冲你拱手微笑。]],["enterable"]=1,["id"]=[[fb16_06]],["item1"]=[[bfitem1]],["name"]=[[迎客亭]],["permission"]=1,["role1"]=[[znq3cd8]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_07]],["visible"]=1},["fb16_07"]={["down"]=[[fb16_06]],["dsc"]=[[这里是桃庄的百木园，你一走到这里，就象走到了一个连绵无尽的小森林一样，这里无数的松树，柏树，白杨，还有很多叫不出来名字的异种苗木，其中有一株黄松特别的粗壮，在它的茂密的枝叶后面，似乎藏着什么秘密。旁边立着一块牌子。]],["enterable"]=1,["id"]=[[fb16_07]],["left"]=[[fb16_09]],["leftDown"]=[[fb16_08]],["name"]=[[百木园]],["permission"]=1,["right"]=[[fb16_25]],["role1"]=[[fb16r07_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_16]],["visible"]=1},["fb16_08"]={["dsc"]=[[你终于爬上了松树的顶端，在这里你可以看见一片密密厚厚的树林，你踩在这里，如同踩在一块草地上一样，远处可以看见隐隐约约的一座巍峨的高山。]],["enterable"]=1,["id"]=[[fb16_08]],["item1"]=[[fb16item10]],["item2"]=[[fb16item11]],["item3"]=[[fb16item12]],["name"]=[[松树顶]],["permission"]=1,["rightUp"]=[[fb16_07]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb16_09"]={["dsc"]=[[这是一间没有任何东西的房子，四壁空荡荡的，好像是一间刚修好的，还没有来得及进行装饰的房间，正中的墙上画着一幅壁画，相当的醒目，画着九天十万神魔歃血为盟，十万滴魔血化做了一只鲜红的鹦鹉，鹦鹉的眼睛竟然是用非常罕见的朱雀石做成的。]],["enterable"]=1,["id"]=[[fb16_09]],["item1"]=[[fb16item5]],["item2"]=[[fb16item102]],["item3"]=[[fb16item103]],["name"]=[[偏房]],["permission"]=2,["right"]=[[fb16_07]],["role1"]=[[fb16r09_100]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb16_10"]={["dsc"]=[[这是一间不大的房间，房间里摆着一排排的书架和很多书，在书架的两旁靠着几具死人的骸骨，有一具的胸骨之中还插着一柄剑。]],["enterable"]=1,["id"]=[[fb16_10]],["name"]=[[密室]],["permission"]=2,["right"]=[[fb16_09]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_11]],["visible"]=1},["fb16_11"]={["down"]=[[fb16_10]],["dsc"]=[[你现在在书架的顶部，从这里你可以看见整个密室的情况，除了几具白骨以外，确实没有什么值得你怀疑的东西，但你发现书架的顶部非常不合适的铺着一块红绸。]],["enterable"]=1,["id"]=[[fb16_11]],["item1"]=[[fb16item14]],["name"]=[[书架顶部]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb16_12"]={["down"]=[[fb16_25]],["dsc"]=[[这里就是奇槐坡了，这里种着大大小小，千奇百怪的槐树，有的槐树一直向天，有的又曲折盘绕，你从这里隐隐约约听到一阵阵的琴声，似有似无，若隐若现。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb16_12]],["item1"]=[[bfitem3]],["left"]=[[fb16_25]],["name"]=[[奇槐坡]],["permission"]=2,["right"]=[[fb16_13]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_25]],["visible"]=1},["fb16_13"]={["dsc"]=[[你走到这条小路上，前面已经可以隐隐约约看到一座小小的院落的影子，你可以非常的肯定，琴声就是从这个小院里发出来的，想到立刻就可以见到大庄主鼓笙客了，你不禁一阵紧张。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb16_13]],["left"]=[[fb16_12]],["name"]=[[小路]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb16_14]],["visible"]=1},["fb16_14"]={["down"]=[[fb16_13]],["dsc"]=[[这是一座看起来非常普通的小小的院落，院子的中间建着一间小屋，小屋也很普通，就是用茅草为顶，砖土为墙，院子里没有什么摆设，只有几堆干木柴放在角落里，其中有一捆特别引人注目。]],["enterable"]=1,["id"]=[[fb16_14]],["left"]=[[fb16_15]],["name"]=[[琴音小院]],["permission"]=2,["role1"]=[[fb16r14_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb16_15"]={["dsc"]=[[你进了这间小屋以后，发现这里竟然和你想象的差别很大，这里虽然不能说是金碧辉煌，但到处都是玉制的物器，玉桌，玉椅，玉屏风，玉茶壶，玉杯......数不胜数。墙上挂着一根绿玉萧和一具白玉瑶琴。]],["enterable"]=1,["id"]=[[fb16_15]],["item1"]=[[fb16item16]],["name"]=[[小屋]],["permission"]=2,["right"]=[[fb16_14]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb16_16"]={["down"]=[[fb16_07]],["dsc"]=[[这里是桃庄的内院，从这里走过去就可以找到四位庄主，这里似乎非常安静，可以听见落叶触地的声音，但又似乎非常吵闹，经常可以听到嘈杂的琴声，但这琴声又可以将你的心弦打乱，你真不知道该怎么形容这个地方。有一位壮年的汉子，腰悬宝剑守在院门口。]],["enterable"]=1,["id"]=[[fb16_16]],["item1"]=[[fb16item8]],["item2"]=[[lylitem1]],["name"]=[[内院]],["permission"]=1,["role1"]=[[fb16r16_1]],["role2"]=[[fb16r16_2]],["role3"]=[[fb16r16_3]],["role4"]=[[tmnpc01a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_17]],["visible"]=1},["fb16_17"]={["down"]=[[fb16_16]],["dsc"]=[[这是一条长长的走廊，走廊两边是四位庄主中的其他三位平时休息和练功的地方，这里的左边是书室，右边是画室，三庄主挥毫客和四庄主妙笔客在闲来无事的时候，便到那里面去挥毫，泼墨。]],["enterable"]=1,["id"]=[[fb16_17]],["left"]=[[fb16_18]],["name"]=[[走廊]],["permission"]=2,["right"]=[[fb16_19]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_20]],["visible"]=1},["fb16_18"]={["dsc"]=[[这里是挥毫客的书室，房中有一个大案，案上放着一个笔筒，平铺着一张四尺中堂大小的宣纸，一方端砚，一柄徽墨，一对白玉镇纸，一个寿山笔架，都显出主人对书法的爱好。墙上挂满了主人书写的一幅幅条幅，中堂，对联。]],["enterable"]=1,["id"]=[[fb16_18]],["item1"]=[[fb16item2]],["name"]=[[书室]],["permission"]=2,["right"]=[[fb16_17]],["role1"]=[[fb16r18_1]],["role2"]=[[fb16r18_100]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb16_19"]={["dsc"]=[[这里是妙笔客的画室，这里的陈设和书室差不多，唯一不同的是这里的墙上并没有挂妙笔客的丹青妙笔，而是挂了许多前朝名家的名画，属于妙笔客自己的是一幅写着《兵车行》的中堂。]],["enterable"]=1,["id"]=[[fb16_19]],["item1"]=[[fb16item100]],["left"]=[[fb16_17]],["name"]=[[画室]],["permission"]=2,["role1"]=[[fb16r19_100]],["role2"]=[[fb16r19_101]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb16_20"]={["down"]=[[fb16_17]],["dsc"]=[[这是一条长长的走廊，走廊两边是四位庄主中的其他三位平时休息和练功的地方，这里的左边是棋室，右边则是桃庄弟子感觉劳顿的时候休息的地方，二庄主对弈客不分昼夜都在棋室里研究他那些不知道哪儿找来的古棋谱。]],["enterable"]=1,["id"]=[[fb16_20]],["left"]=[[fb16_21]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb16_22]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_23]],["visible"]=1},["fb16_21"]={["dsc"]=[[这里便是二庄主对弈客的棋室了，棋室里两张石凳，一张石几，石几上用对弈客的指力刻着纵横九九八十一道，这里除了简单的放着两盒用玉做成的棋子外，什么都没有，显是怕双方对弈时分心。]],["enterable"]=1,["id"]=[[fb16_21]],["item1"]=[[bfitem2]],["left"]=[[fb16_40]],["name"]=[[棋室]],["permission"]=2,["right"]=[[fb16_20]],["role1"]=[[fb16r21_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb16_22"]={["dsc"]=[[这里是桃庄弟子练功劳累的时候，休息的地方，这里经常可以听到如雷的鼾声，这里简单的放着几张垫子，几床棉被，几个枕头，很多桃庄弟子一进这里，倒头便睡，显是过于疲劳的缘故。]],["enterable"]=1,["id"]=[[fb16_22]],["item1"]=[[fb16item17]],["item2"]=[[fb16item17]],["left"]=[[fb16_20]],["name"]=[[休息室]],["permission"]=2,["role1"]=[[fb16r22_1]],["role2"]=[[fb16r22_2]],["role3"]=[[fb16r22_100]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb16_23"]={["down"]=[[fb16_20]],["dsc"]=[[走廊到了这里似乎就到了尽头，从走廊的那一头传来阵阵的烧饭的香味，饥肠辘辘的你，走到这里，再也忍受不了那种扑面而来的香气的诱惑，只有加快脚步，去看个究竟。]],["enterable"]=1,["id"]=[[fb16_23]],["name"]=[[走廊]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb16_24]],["visible"]=1},["fb16_24"]={["down"]=[[fb16_23]],["dsc"]=[[你顺着香味走到了桃庄的厨房，一位厨师正站在灶台后面笑眯眯的看着你，他手上拿着一柄铁勺，用力的把锅里煮着的一大堆食物搅匀，桃庄的弟子们如果饿了，就到这里来问这位厨师能不能吃饭，一般来说，他们都不会遭到拒绝的。]],["enterable"]=1,["id"]=[[fb16_24]],["name"]=[[厨房]],["permission"]=2,["role1"]=[[fb16r24_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb16_25"]={["down"]=[[fb16_25]],["dsc"]=[[这里是桃庄的百木园，你一走到这里，就象走到了一个连绵无尽的小森林一样，这里无数的松树，柏树，白杨，还有很多叫不出来名字的异种苗木，你走在其中，只想把这片树林尽情的欣赏一遍，永不出去才好。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb16_25]],["left"]=[[fb16_07]],["name"]=[[百木园]],["permission"]=2,["right"]=[[fb16_26]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_25]],["visible"]=1},["fb16_26"]={["down"]=[[fb16_26]],["dsc"]=[[这里是桃庄的百木园，你一走到这里，就象走到了一个连绵无尽的小森林一样，这里无数的松树，柏树，白杨，还有很多叫不出来名字的异种苗木，你走在其中，只想把这片树林尽情的欣赏一遍，永不出去才好。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb16_26]],["left"]=[[fb16_26]],["name"]=[[百木园]],["permission"]=2,["right"]=[[fb16_25]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_27]],["visible"]=1},["fb16_27"]={["down"]=[[fb16_27]],["dsc"]=[[这里是桃庄的百木园，你一走到这里，就象走到了一个连绵无尽的小森林一样，这里无数的松树，柏树，白杨，还有很多叫不出来名字的异种苗木，你走在其中，只想把这片树林尽情的欣赏一遍，永不出去才好。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb16_27]],["left"]=[[fb16_25]],["name"]=[[百木园]],["permission"]=2,["right"]=[[fb16_28]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_27]],["visible"]=1},["fb16_28"]={["down"]=[[fb16_29]],["dsc"]=[[这里是桃庄的百木园，你一走到这里，就象走到了一个连绵无尽的小森林一样，这里无数的松树，柏树，白杨，还有很多叫不出来名字的异种苗木，你走在其中，只想把这片树林尽情的欣赏一遍，永不出去才好。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb16_28]],["left"]=[[fb16_25]],["name"]=[[百木园]],["permission"]=2,["right"]=[[fb16_28]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_28]],["visible"]=1},["fb16_29"]={["down"]=[[fb16_30]],["dsc"]=[[这里是桃庄的百木园，你一走到这里，就象走到了一个连绵无尽的小森林一样，这里无数的松树，柏树，白杨，还有很多叫不出来名字的异种苗木，你走在其中，只想把这片树林尽情的欣赏一遍，永不出去才好。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb16_29]],["left"]=[[fb16_28]],["name"]=[[百木园]],["permission"]=2,["right"]=[[fb16_28]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_29]],["visible"]=1},["fb16_30"]={["down"]=[[fb16_32]],["dsc"]=[[这里是桃庄的百木园，你一走到这里，就象走到了一个连绵无尽的小森林一样，这里无数的松树，柏树，白杨，还有很多叫不出来名字的异种苗木，你走在其中，只想把这片树林尽情的欣赏一遍，永不出去才好。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb16_30]],["left"]=[[fb16_27]],["name"]=[[百木园]],["permission"]=2,["right"]=[[fb16_31]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_28]],["visible"]=1},["fb16_31"]={["down"]=[[fb16_30]],["dsc"]=[[这里是桃庄的百木园，你一走到这里，就象走到了一个连绵无尽的小森林一样，这里无数的松树，柏树，白杨，还有很多叫不出来名字的异种苗木，你走在其中，只想把这片树林尽情的欣赏一遍，永不出去才好。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb16_31]],["left"]=[[fb16_27]],["name"]=[[百木园]],["permission"]=2,["right"]=[[fb16_32]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_12]],["visible"]=1},["fb16_32"]={["down"]=[[fb16_39]],["dsc"]=[[这里是桃庄的百木园，你一走到这里，就象走到了一个连绵无尽的小森林一样，这里无数的松树，柏树，白杨，还有很多叫不出来名字的异种苗木，你走在其中，只想把这片树林尽情的欣赏一遍，永不出去才好。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb16_32]],["left"]=[[fb16_25]],["name"]=[[百木园]],["permission"]=2,["right"]=[[fb16_27]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_29]],["visible"]=1},["fb16_33"]={["dsc"]=[[这是一条昏暗潮湿的地道，地道很长，两边点着两根不太明亮的火把，地道两旁的墙壁上画着很多不知道出自何人之手的壁画，而且画得相当难看，你加快脚步，想知道地道的尽头是什么地方。]],["enterable"]=1,["id"]=[[fb16_33]],["left"]=[[fb16_33]],["name"]=[[桃庄密道]],["permission"]=2,["right"]=[[fb16_33]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_34]],["visible"]=1},["fb16_34"]={["down"]=[[fb16_33]],["dsc"]=[[这是一条昏暗潮湿的地道，地道很长，两边点着两根不太明亮的火把，地道两旁的墙壁上画着很多不知道出自何人之手的壁画，而且画得相当难看，你加快脚步，想知道地道的尽头是什么地方。]],["enterable"]=1,["id"]=[[fb16_34]],["left"]=[[fb16_33]],["name"]=[[桃庄密道]],["permission"]=2,["right"]=[[fb16_33]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_35]],["visible"]=1},["fb16_35"]={["down"]=[[fb16_36]],["dsc"]=[[这是一条昏暗潮湿的地道，地道很长，两边点着两根不太明亮的火把，地道两旁的墙壁上的壁画画得相当难看，你加快脚步，想知道地道的尽头是什么地方。突然之间你发现这里的地面已经是木板拼成的了。]],["enterable"]=1,["id"]=[[fb16_35]],["left"]=[[fb16_33]],["name"]=[[桃庄密道]],["permission"]=2,["right"]=[[fb16_33]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_33]],["visible"]=1},["fb16_36"]={["down"]=[[fb16_33]],["dsc"]=[[你一到这里，迎面就闻到一股腐烂的泥土的味道，不过从前面的亮光中，你又看到了希望，你不禁开始加快脚步，想看看那里到底有些什么东西。]],["enterable"]=1,["id"]=[[fb16_36]],["name"]=[[甬道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb16_37]],["visible"]=1},["fb16_37"]={["down"]=[[fb16_37]],["dsc"]=[[你一到这里，迎面就闻到一股腐烂的泥土的味道，不过从前面的亮光中，你又看到了希望，你不禁开始加快脚步，想看看那里到底有些什么东西。]],["enterable"]=1,["id"]=[[fb16_37]],["name"]=[[甬道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb16_38]],["visible"]=1},["fb16_38"]={["dsc"]=[[你一走到这里，突然一片明亮，原来这里竟然是古代蚕丛王的陵墓，中间停放着一具棺木，棺木的上方悬挂着一颗鹅蛋一般大小的夜明珠，把这里照得异常明亮，棺木的正中放着一本书，书看起来很陈旧，似乎是一位前辈异人留下的。]],["enterable"]=1,["id"]=[[fb16_38]],["name"]=[[古皇陵]],["permission"]=2,["right"]=[[fb16_01]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb16_39"]={["dsc"]=[[这里黑黑暗暗，几乎伸手不见五指。唯一的光亮来自墙上忽明忽暗的松油灯。地上和墙上布满了暗红色的血痕，散发出阵阵腥气。不断传来的喘息声在死沉的地牢里回荡，令人毛骨耸然。从地牢的墙缝里透出几缕阳光。]],["enterable"]=1,["id"]=[[fb16_39]],["name"]=[[桃庄地牢]],["permission"]=2,["role1"]=[[fb16r39_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb16_33]],["visible"]=1},["fb16_40"]={["dsc"]=[[这是一间小小的密室，里面有一张小小的书桌，书桌上摆放着一些东西。]],["enterable"]=1,["id"]=[[fb16_40]],["name"]=[[密室]],["permission"]=2,["right"]=[[fb16_21]],["stepMusic"]=[[jiaobu]],["visible"]=1}}000000000000000